export const usePluginUpdateConfiguration = <
  TError =
    | BadRequestResponse
    | UnauthorisedResponse
    | NotFoundResponse
    | InternalServerErrorResponse,
>(
  pluginInstanceId: string,
  options?: {
    swr?: SWRMutationConfiguration<
      Awaited<ReturnType<typeof pluginUpdateConfiguration>>,
      TError,
      Key,
      PluginUpdateConfigurationBody | undefined,
      Awaited<ReturnType<typeof pluginUpdateConfiguration>>
    > & { swrKey?: string };
    request?: SecondParameter<typeof fetcher>;
  },
) => {
  const { swr: swrOptions, request: requestOptions } = options ?? {};

  const swrKey =
    swrOptions?.swrKey ??
    getPluginUpdateConfigurationMutationKey(pluginInstanceId);
  const swrFn = getPluginUpdateConfigurationMutationFetcher(
    pluginInstanceId,
    requestOptions,
  );

  const query = useSWRMutation(swrKey, swrFn, swrOptions);

  return {
    swrKey,
    ...query,
  };
};
